import { BaseMessageChannel, MessageChannelFactory } from '../message-channels';
import { GetMessageEvent, IArcadeWinnerPayload, IChatChildEvents, IChatParentEvents, IMessageReceivedPayload, IChatColourPayload, IChatFullScreenPayload, IProvideChatColoursPayload, IChatLinksPayload } from '../types';

export class ChatConnection implements IChatParentEvents {
    private messageChannel: BaseMessageChannel<IChatParentEvents, IChatChildEvents>;
    private handlers: IChatChildEvents;

    constructor(handlers: IChatChildEvents) {
        this.messageChannel = MessageChannelFactory.create({
            type: 'web',
            target: window,
            source: 'chat',
            onMessageCallback: (event) => this.onMessage(event)
        });
        this.handlers = handlers;
    }

    public onInit(): void {
        this.messageChannel.send('onInit', void 0);
    }

    public onLoaded(): void {
        this.messageChannel.send('onLoaded', void 0);
    }

    public goToLobby(): void {
        this.messageChannel.send('goToLobby', void 0);
    }

    public onKeyboardOpened(payload: { isOpen: boolean }): void {
        this.messageChannel.send('onKeyboardOpened', payload);
    }

    public setChatColour(payload: IChatColourPayload): void {
        this.messageChannel.send('setChatColour', payload);
    }

    public toggleFullScreen(payload: IChatFullScreenPayload): void {
        this.messageChannel.send('toggleFullScreen', payload);
    }

    public onMessageReceived(message: IMessageReceivedPayload): void {
        this.messageChannel.send('onMessageReceived', message);
    }

    public onLiveChatClicked(): void {
        this.messageChannel.send('onLiveChatClicked', void 0);
    }

    public onLinkClicked(payload: IChatLinksPayload): void {
        this.messageChannel.send('onLinkClicked', payload);
    }

    public onArcadeWinner(response: IArcadeWinnerPayload): void {
        this.messageChannel.send('onArcadeWinner', response);
    }

    public onChatNotification(): void {
        this.messageChannel.send('onChatNotification', void 0);
    }

    private onMessage(event: GetMessageEvent<IChatChildEvents, keyof IChatChildEvents>) {
        if (this.handlers[event.data.type]) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            this.handlers[event.data.type](event.data.payload as any);
        }
    }

    public provideAllChatColours(response: IProvideChatColoursPayload[]): void {
        this.messageChannel.send('provideAllChatColours', response);
    }
}
